async function calculateFreight(){
 const input=document.getElementById('freightCep'),results=document.getElementById('freightResults'),total=document.getElementById('freightTotal'),cep=cleanCep(input.value);
 if(cep.length!==8){results.innerHTML='<div class="freight-error">Digite um CEP de destino válido com 8 números.</div>';total.style.display='none';return;}
 input.value=formatCep(cep);selectedFreight=null;total.style.display='none';results.innerHTML='<div class="freight-loading">⏳ Consultando tarifas reais...</div>';
 if(!cloudReady||!supabaseClient){results.innerHTML='<div class="freight-error">A conexão com o servidor ainda não está disponível.</div>';return;}
 try{
  const products=cart.map(p=>{const s=shippingSpecForProduct(p);return{id:String(p.code||p.name||'produto'),width:s.width,height:s.height,length:s.length,weight:s.weight,insurance_value:Number(eprice(p)||0),quantity:Number(p._qty||1)}});
  const {data,error}=await supabaseClient.functions.invoke('melhorenvio-quote',{body:{fromPostalCode:'84272402',toPostalCode:cep,products}});
  if(error)throw error;
  const opts=Array.isArray(data?.quotes)?data.quotes:[];
  if(!opts.length){results.innerHTML='<div class="freight-error">Não encontramos uma opção de envio para este CEP.'+(data?.error?'<br><small>'+String(data.error)+'</small>':'')+'</div>';return;}
  window.__freightQuotes=opts;
  results.innerHTML=opts.map((o,i)=>'<button type="button" class="freight-option" data-freight-index="'+i+'" onclick="selectFreightByIndex('+i+')"><span><b>🚚 '+String(o.company?o.company+' — ':'')+String(o.name||'Frete')+'</b><small>Prazo: '+String(o.days??'consulte')+' dias úteis</small></span><strong>'+moneyBR(Number(o.price))+'</strong></button>').join('')+'<div class="freight-note">✅ Cotação calculada pelo Melhor Envio para o CEP informado.</div>';
 }catch(e){console.error('Melhor Envio:',e);results.innerHTML='<div class="freight-error">Não foi possível calcular o frete agora. Tente novamente em alguns segundos.</div>';}
}
window.selectFreight=function(id,price,days){
 const numericPrice=Number(price);if(!Number.isFinite(numericPrice)||numericPrice<=0)return;
 document.querySelectorAll('.freight-option').forEach(el=>el.classList.toggle('freight-selected',el.dataset.freight===String(id)));
 selectedFreight={id:String(id),price:numericPrice,days:days||''};
 const total=document.getElementById('freightTotal'),totalValue=document.getElementById('freightTotalValue'),method=document.getElementById('freightSelectedMethod'),selectedDays=document.getElementById('freightSelectedDays'),grandHint=document.getElementById('freightGrandTotalHint'),productsTotal=cart.reduce((s,p)=>s+eprice(p)*(p._qty||1),0);
 if(total)total.style.display='flex';if(totalValue)totalValue.textContent=moneyBR(numericPrice);if(method)method.textContent=(id||'').toUpperCase();if(selectedDays)selectedDays.textContent=days?'⏱️ '+days:'';
 if(grandHint){grandHint.style.display='flex';grandHint.innerHTML='<span>🛒 Total dos produtos</span><b>'+moneyBR(productsTotal)+'</b><span>+</span><span>🚚 Frete</span><b>'+moneyBR(numericPrice)+'</b><strong>= '+moneyBR(productsTotal+numericPrice)+'</strong>';}
};
