(function setupBuyerFields(){
  // IMPORTANTE: os dados do cliente NÃO ficam salvos no localStorage.
  // Cada novo cliente começa com o formulário vazio.
  try{ localStorage.removeItem('eletroshopp_buyer_data'); }catch(e){}
  const ids=['buyerName','buyerPhone','freightCep','buyerCity','buyerAddress','buyerNumber','buyerNeighborhood','buyerComplement','buyerNote'];
  const get=id=>document.getElementById(id);
  if(ids.some(id=>!get(id))) return;

  ids.forEach(id=>{
    const el=get(id);
    el.value='';
    el.setAttribute('autocomplete', id==='buyerName' ? 'name' :
      id==='buyerPhone' ? 'tel' :
      id==='freightCep' ? 'postal-code' :
      id==='buyerAddress' ? 'street-address' :
      id==='buyerNumber' ? 'address-line2' :
      id==='buyerCity' ? 'address-level2' :
      id==='buyerNeighborhood' ? 'address-level3' : 'off');
  });

  // O CEP continua sendo automático: ao informar o CEP, buscamos
  // logradouro, bairro e cidade/UF pelo ViaCEP.
  let lastCep='', timer=null;
  async function fillAddressByCep(){
    const cep=cleanCep(get('freightCep').value);
    if(cep.length!==8 || cep===lastCep)return;
    lastCep=cep;
    try{
      const response=await fetch('https://viacep.com.br/ws/'+cep+'/json/');
      if(!response.ok) throw new Error('CEP lookup failed');
      const data=await response.json();
      if(data.erro) return;
      if(data.logradouro) get('buyerAddress').value=data.logradouro;
      if(data.bairro) get('buyerNeighborhood').value=data.bairro;
      if(data.localidade || data.uf) get('buyerCity').value=[data.localidade,data.uf].filter(Boolean).join('/');
    }catch(e){
      console.warn('ViaCEP:',e);
    }
  }

  get('freightCep').addEventListener('input',()=>{
    const cep=cleanCep(get('freightCep').value);
    if(cep.length<8)lastCep='';
    clearTimeout(timer);
    if(cep.length===8)timer=setTimeout(fillAddressByCep,250);
  });
  get('freightCep').addEventListener('blur',fillAddressByCep);

  // Máscara simples de WhatsApp/telefone.
  get('buyerPhone').addEventListener('input',e=>{
    let v=e.target.value.replace(/\D/g,'').slice(0,11);
    if(v.length<=10) v=v.replace(/^(\d{2})(\d)/,'($1) $2').replace(/(\d{4})(\d)/,'$1-$2');
    else v=v.replace(/^(\d{2})(\d)/,'($1) $2').replace(/(\d{5})(\d)/,'$1-$2');
    e.target.value=v;
  });
})();
